import React, { useState } from 'react';
import './ChipFilter.css';

type FilterLabel = 'All' | 'Active' | 'Archived' | 'Starred';

const FILTER_LABELS: FilterLabel[] = ['All', 'Active', 'Archived', 'Starred'];

export function ChipFilter(): React.ReactElement {
  const [pressed, setPressed] = useState<FilterLabel>('All');

  return (
    <div className="chip-bar">
      {FILTER_LABELS.map((label) => (
        <button
          key={label}
          type="button"
          className="chip"
          aria-pressed={pressed === label}
          onClick={() => setPressed(label)}
        >
          {label}
        </button>
      ))}
    </div>
  );
}
